  $c.Padding = & $ui.Pad (& $wn.Sc $PadX) (& $wn.Sc (18 + $tp)) (& $wn.Sc $PadX) (& $wn.Sc 18); $c.Margin = & $ui.Pad 0 0 0 (& $wn.Sc 14)
  & $ui.Ring $c
